/**
 * Cut list (MTO Pilot → isometric → Cut list), after the client's Excel "Chameleon Cut list" (sheet Calculation):
 *   N  = TOTAL LENGTH + EXTRA LENGTH − BEVEL × 2
 *   O…R = take-off (SIZE in sheet Codes) of FIT 1…FIT 4, 0 when no fitting is chosen
 *   PASTUK LENGTH = N − O − P − Q − R
 * The fitting catalog (`cut_fittings`) holds the Codes sheet: code, description, diameter and take-off in mm, plus a readable
 * name for the dropdown (`fittingName`). The rows ship in `cut-list-fittings-data.ts`, generated by scripts/build-cut-list-fittings.ts.
 */
import type { Row } from './types.ts';

export const CUT_LIST_FITS = [1, 2, 3, 4] as const;
export const fitField = (slot: number) => `fit${slot}Id`;
export const takeoffField = (slot: number) => `takeoff${slot}`;

/** One row of the shipped fitting catalog: [row number in the Codes sheet, code, description, diameter, take-off mm]. */
export type FittingCatalogRow = [ref: number, code: string, description: string, diameter: string, takeoff: number];

const number = (value: unknown): number => {
  if (value === '' || value === null || value === undefined) return 0;
  const parsed = typeof value === 'number' ? value : Number(String(value).trim().replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : 0;
};
/** Rounded to 1e-6 so a stored length carries no floating-point noise (Excel shows 451.53999999 as 451.54). */
export const roundLength = (value: number) => Math.round(value * 1e6) / 1e6;

/** A typed length: a decimal comma or point; an empty text is no value (null). Anything else stays as typed (the server refuses it). */
export function parseLength(text: string): number | null | string {
  const trimmed = text.trim();
  if (!trimmed) return null;
  const parsed = Number(trimmed.replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : trimmed;
}

export type CutLengthInput = Record<string, unknown>;
/** The Excel formula: net length (N) and PASTUK LENGTH (S) from the take-offs of the chosen fittings (O…R). */
export function cutLength(values: CutLengthInput, takeoffs: readonly unknown[]) {
  const net = roundLength(number(values.totalLength) + number(values.extraLength) - number(values.bevel) * 2);
  const deducted = takeoffs.map(number);
  return { net, takeoffs: deducted, length: roundLength(deducted.reduce((rest, takeoff) => rest - takeoff, net)) };
}

/** A line of the calculation table: it has a total length. Earlier lines (pieces × entered cut length) have none. */
export const isCalculationLine = (line: Partial<Row> | Record<string, unknown>) => line.totalLength !== undefined && line.totalLength !== null && line.totalLength !== '';

/**
 * Take-offs and PASTUK LENGTH of a stored line with the catalog as it is now. An earlier line keeps its entered cut length.
 * A line whose take-offs are fixed (`takeoffsFixed`: a completed revision, or one that keeps the previous standards,
 * shared/cut-list-revisions.ts) keeps the take-offs stored with it, whatever the catalog says now.
 */
export function lineLengths(line: Row, fittings: ReadonlyMap<string, Row>) {
  const takeoffs = CUT_LIST_FITS.map(slot => { const id = String(line[fitField(slot)] ?? ''); return !id ? 0 : line.takeoffsFixed === true ? number(line[takeoffField(slot)]) : number(fittings.get(id)?.takeoff ?? line[takeoffField(slot)]); });
  if (!isCalculationLine(line)) return { calculated: false, net: null, takeoffs, length: number(line.lengthMm) };
  return { calculated: true, ...cutLength(line, takeoffs) };
}

/** Lines of an isometric in line-number order (numbers first, numerically; then the rest by text). */
export const sortLines = (lines: Row[]) => [...lines].sort((a, b) => String(a.name ?? '').localeCompare(String(b.name ?? ''), 'en', { numeric: true }) || a._createdAt.localeCompare(b._createdAt));
/** The next free line number of an isometric (every line, archived ones too, so a restored line keeps its number). */
export const nextLineName = (lines: readonly Record<string, unknown>[]) => String(lines.reduce((max, line) => { const value = Number(String(line.name ?? '').trim()); return Number.isSafeInteger(value) && value > max ? value : max; }, 0) + 1);

// ── Diameters ────────────────────────────────────────────────────────────────

/** A diameter text compared loosely: `1 1/2"`, `1.1/2"`, `1.1/2in` and `1.1/2''` are the same size; `DN50` stays `dn50`. */
export function diameterKey(text: unknown) {
  return String(text ?? '').trim().toLowerCase().replace(/''/g, '"').replace(/(\d)\s*in$/, '$1').replace(/(\d)[\s.]+(\d+\/\d+)/g, '$1.$2').replace(/["\s]/g, '');
}
/** The sizes a fitting fits (a reducer or reducing tee two, an olet its branch and run); none for a fitting of every size. */
export function fittingSizes(diameter: unknown) {
  const text = String(diameter ?? '').trim();
  if (!text || /^all\b/i.test(text)) return [];
  return text.split(/\s*(?:[xX]|\$)\s*/).map(diameterKey).filter(Boolean);
}
/** A fitting for the row's DIA: one of its sizes is that diameter, or it is a fitting of every size (ring distance, slip-on flange). */
export function fittingFitsDiameter(fitting: Record<string, unknown>, dia: unknown) {
  const key = diameterKey(dia), sizes = fittingSizes(fitting.diameter);
  return Boolean(key) && (!sizes.length || sizes.includes(key));
}

// ── Readable names ───────────────────────────────────────────────────────────

/** A size of a code (`1.1/4`, `22`, `DN250`) as the cut list writes it: inches with `"`, DN as is. */
const size = (value: string) => /^dn/i.test(value) ? value.toUpperCase() : `${value.trim()}"`;
const inches = (value: string) => { const match = /^(\d+)(?:\.(\d+)\/(\d+))?$|^(\d+)\/(\d+)$/.exec(value.trim()); if (!match) return Number.NaN; return match[4] ? Number(match[4]) / Number(match[5]) : Number(match[1]) + (match[2] ? Number(match[2]) / Number(match[3]) : 0); };
/** Two sizes larger first: `R-1/2x3/4in-` is a reducer 3/4" x 1/2". */
const pair = (a: string, b: string) => { const [large, small] = inches(a) >= inches(b) ? [a, b] : [b, a]; return `${size(large)} x ${size(small)}`; };
/** The diameter column as the cut list writes it (`8''` → `8"`, `1 1/2"` → `1.1/2"`, a bare `2` → `2"`). */
const columnSize = (diameter: string) => { const text = diameter.trim().replace(/''/g, '"').replace(/(\d)\s+(\d+\/\d+)/, '$1.$2'); return /^[\d./]+$/.test(text) ? `${text}"` : text; };
const angle = (value: string) => `${value.replace(',', '.')}°`;

interface NameRule { pattern: RegExp; name: (match: RegExpExecArray, row: { description: string; diameter: string }) => string }
/** Rules by code prefix, most specific first (every prefix of the client's Codes sheet; tests/cut-list.test.ts covers each). */
const NAME_RULES: NameRule[] = [
  { pattern: /^WN-(DN\d+)-(PN\d+)$/i, name: m => `Weld neck flange ${m[1].toUpperCase()} ${m[2].toUpperCase()}` },
  { pattern: /^WN-(.+?)in-(\d+)$/i, name: m => `Weld neck flange ${size(m[1])} LBS${m[2]}` },
  { pattern: /^BL-(DN\d+)-(PN\d+)$/i, name: m => `Blind flange ${m[1].toUpperCase()} ${m[2].toUpperCase()}` },
  { pattern: /^SBL-(.+?)-(\d+)-(CS|RVS|SS)$/i, name: m => `Spectacle blind ${size(m[1])} LBS${m[2]} ${m[3].toUpperCase() === 'CS' ? 'CS' : 'SS'}` },
  { pattern: /^CAP-(.+?)in-?$/i, name: m => `Cap ${size(m[1])}` },
  { pattern: /^e(45|90)sw-(.+?)in-?$/i, name: (m, row) => `${m[1]}° Elbow SW ${size(m[2])}${swClass(row.description)}` },
  { pattern: /^e(45|90)-(.+?)in-?$/i, name: m => `${m[1]}° Elbow ${size(m[2])}` },
  { pattern: /^e(\d+(?:[.,]\d+)?)-(.+?)in-?$/i, name: m => `Elbow cutback ${angle(m[1])} ${size(m[2])}` },
  { pattern: /^Tsw-(.+?)in-(\d+)$/i, name: m => `Equal tee SW ${size(m[1])} Class ${m[2]}` },
  { pattern: /^TR-(.+?)x(.+?)in-?$/i, name: m => `Reducing tee ${pair(m[1], m[2])}` },
  { pattern: /^T-(.+?)in-?$/i, name: m => `Equal tee ${size(m[1])}` },
  { pattern: /^R-(.+?)x(.+?)in-?$/i, name: m => `Reducer ${pair(m[1], m[2])}` },
  { pattern: /^WoletSW-(.+?)in\((\d+)\)$/i, name: m => `Weldolet SW ${size(m[1])} Class ${m[2]}` },
  { pattern: /^Wolet-(.+?)in-\(S([\d/]+)\)-P(.+?)(?:in)?$/i, name: m => `Weldolet ${size(m[1])} SCH ${m[2]} on ${size(m[3])} run` },
  { pattern: /^Nolet-(.+?)in-\(S([\d/]+)\)-P(.+?)(?:in)?$/i, name: m => `Nipolet ${size(m[1])} SCH ${m[2]} on ${size(m[3])} run` },
  { pattern: /^HP-(.+?)in-?$/i, name: m => `Half pipe diameter ${size(m[1])}` },
  { pattern: /^StEd-(.+?)in-ASME$/i, name: m => `Stub end ${size(m[1])} ASME B16.9` },
  { pattern: /^StEd-(.+?)in-MSS$/i, name: m => `Stub end ${size(m[1])} MSS SP-43` },
  { pattern: /^GoV-(.+?)in-(\d+)-(RF|RTJ)$/i, name: m => `Globe valve ${size(m[1])} Class ${m[2]} ${m[3].toUpperCase()}` },
  { pattern: /^GtVsw-(.+?)in-(\d+)$/i, name: m => `Gate valve SW ${size(m[1])} Class ${m[2]}` },
  { pattern: /^GtV-(.+?)in-(\d+)-(RF|RTJ)$/i, name: m => `Gate valve ${size(m[1])} Class ${m[2]} ${m[3].toUpperCase()}` },
  { pattern: /^FSW/i, name: (_, row) => `Socket weld flange ${columnSize(row.diameter)} CL150${swClass(row.description)}` },
  { pattern: /^SWD$/i, name: () => 'Socket weld ring distance' },
  { pattern: /^SoF\b/i, name: () => 'Slip-on flange (all sizes)' },
];
/** " Class 3000" of a socket-weld description (`… SW 3000`, `… SW Class 3000`). */
function swClass(description: string) { const match = /(?:SW|Class)\s+(?:Class\s+)?(\d{3,4})\s*$/i.exec(description.trim()); return match ? ` Class ${match[1]}` : ''; }

/** The readable name of a fitting from its code, description and diameter; a code no rule knows reads as its description and diameter. */
export function fittingName(row: { code: unknown; description?: unknown; diameter?: unknown }) {
  const code = String(row.code ?? '').trim(), description = String(row.description ?? '').replace(/\s+/g, ' ').trim(), diameter = String(row.diameter ?? '').trim();
  for (const rule of NAME_RULES) { const match = rule.pattern.exec(code); if (match) return rule.name(match, { description, diameter }); }
  const dia = diameter ? columnSize(diameter) : '';
  return [description || code, dia && !description.includes(dia) ? dia : ''].filter(Boolean).join(' ');
}

/** Element types of the Cut list standards page filter, by code prefix (most specific first); a code no rule knows is "Other". */
const FITTING_TYPE_RULES: [string, RegExp][] = [
  ['Weld neck flange', /^WN-/i], ['Blind flange', /^BL-/i], ['Spectacle blind', /^SBL-/i], ['Cap', /^CAP-/i],
  ['Elbow SW', /^e(45|90)sw-/i], ['Elbow', /^e(45|90)-/i], ['Elbow cutback', /^e\d+(?:[.,]\d+)?-/i],
  ['Equal tee SW', /^Tsw-/i], ['Reducing tee', /^TR-/i], ['Equal tee', /^T-/i], ['Reducer', /^R-/i],
  ['Weldolet', /^Wolet(SW)?-/i], ['Nipolet', /^Nolet-/i], ['Half pipe', /^HP-/i], ['Stub end', /^StEd-/i],
  ['Globe valve', /^GoV-/i], ['Gate valve', /^GtV(sw)?-/i], ['Socket weld flange', /^FSW/i], ['Socket weld ring distance', /^SWD$/i], ['Slip-on flange', /^SoF\b/i],
];
export const FITTING_TYPES = [...FITTING_TYPE_RULES.map(([type]) => type), 'Other'];
export const fittingType = (row: Record<string, unknown>) => FITTING_TYPE_RULES.find(([, pattern]) => pattern.test(String(row.code ?? '').trim()))?.[0] ?? 'Other';

/** Words of a search typed in the fitting dropdown: every word must occur in the name, code, description or diameter. */
export function fittingMatches(fitting: Row, query: string) {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return true;
  const text = [fitting.name, fitting.code, fitting.description, fitting.diameter].map(value => String(value ?? '')).join(' ').toLowerCase().replace(/''/g, '"');
  return words.every(word => text.includes(word));
}

/** Columns of the printed cut list (the Excel sheet Print). Heat No and QC are filled in by hand on the paper. */
export const CUT_LIST_PRINT_COLUMNS = ['ISO NAME', 'SHT', 'SPOOL', 'DIA', 'SCH / WT', 'PASTUK LENGTH', 'BEVEL', 'MATERIAL', 'Heat No', 'QC'] as const;
/** The cells of one printed line (lengths with 2 decimals as the Excel shows them). */
export function printCells(line: Row, isoNo: string, spool: string, length: number) {
  const value = (name: string) => String(line[name] ?? '');
  const bevel = line.bevel === null || line.bevel === undefined || line.bevel === '' ? '' : Number(line.bevel);
  return [isoNo, value('sheet'), spool, value('dia'), value('schedule'), roundLength(length), bevel, value('material'), '', ''];
}
export const formatLength = (value: number | null) => value === null || !Number.isFinite(value) ? '' : value.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
